 const [c,set]=useState<Character>(character||{id:uid(),name:'',tagline:'',description:'',greeting:'',definition:'',category:'Roleplay',tags:[],avatar:0,creator:creator.replace(/\s+/g,'').toLowerCase(),visibility:'private'}),[saving,setSaving]=useState(false),[tab,setTab]=useState('Basics'),[tagsText,setTagsText]=useState(character?.tags.join(', ')||'');
